{
  "technical_and_design_decisions": [
    "Extend the Mesos SPI status enumeration to explicitly handle the `undeployed` state instead of defaulting to `unknown`.",
    "Expose a dedicated REST controller endpoint invoking `RabbitBindingCleaner` to trigger RabbitMQ broker artifact cleanup.",
    "Optimize YARN stream and module deployment by staging jar dependencies efficiently and avoiding redundant artifact localization.",
    "Upgrade Spring Hadoop (SHDP) to 2.2.1 GA, maintaining compatibility across supported Hadoop/CDH/HDP variants.",
    "Upgrade Spring Integration to 4.2.2.GA and adjust binder dependencies and interfaces accordingly.",
    "Modify Kafka binder partitioning logic to check partition key expressions regardless of downstream module count.",
    "Upgrade Spring Boot and Spring Cloud Build dependency management descriptors to target versions."
  ],
  "assumptions": [
    "The developer is familiar with Spring Cloud Data Flow / Spring XD architecture, Spring Integration, and associated deployer SPIs.",
    "Existing integration test harnesses and build infrastructure for YARN, Mesos, and Kafka are operational.",
    "Upgrading Spring Integration and Spring Boot/Cloud Build updates will not require extensive refactoring outside the impacted binders.",
    "Documentation will be authored in Reference Guide documentation format (e.g., AsciiDoc)."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Mesos SPI Undeployed Status",
      "activity_description": "Add UNDEPLOYED status enum value and map Mesos framework teardown/unregistered states to UNDEPLOYED instead of UNKNOWN, including unit tests.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Rabbit Binder Cleaner REST Endpoint",
      "activity_description": "Expose REST endpoint mapping to RabbitBindingCleaner service logic, providing RESTful access to purge leftover exchange and queue artifacts.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "YARN Deployer Optimization",
      "activity_description": "Analyze and optimize module packaging and staging in YARN deployer to decrease stream startup overhead and deployment latency.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Upgrade Spring Hadoop (SHDP) to 2.2.1 GA",
      "activity_description": "Update POM dependencies to SHDP 2.2.1 GA, verify Hadoop version compatibility, and adapt broken API calls if present.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Upgrade Spring Integration to 4.2.2.GA",
      "activity_description": "Update Spring Integration build descriptors to 4.2.2.GA and resolve any minor API or messaging channel changes.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Kafka Bus Partitioning Key Enhancement",
      "activity_description": "Refactor Kafka bus message outbound channel adapter logic to evaluate partition key expression even when single downstream module instance exists.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Upgrade Boot and Spring Cloud Build Revisions",
      "activity_description": "Bump parent build versions for Boot and Spring Cloud Build, resolving build/plugin configuration updates.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Document HSQL DB Limitations for Composed Jobs",
      "activity_description": "Write documentation explaining concurrency and locking limitations of HSQL DB when executing composed jobs.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "Integration Testing and Build Verification",
      "activity_description": "Execute comprehensive end-to-end integration test suite across all deployers and binders to ensure regression-free increment.",
      "most_likely_effort": 2.5
    }
  ],
